touch.Tree.pas:
unit Tree;

interface

uses
  System.Generics.Collections, System.SysUtils;

type
  TNode = class
  private
    FField: string;
    FValue: string;
  public
    constructor Create(const AField, AValue: string);
    function IsEmpty: Boolean;
    property Field: string read FField;
    property Value: string read FValue;
  end;

  TQueryTree = class(TObjectList<TNode>)
  public
    constructor Create;
    function AddCondition(const AField, AValue: string): TNode;
    function ToFilter: string;
  end;

implementation

constructor TNode.Create(const AField, AValue: string);
begin
  inherited Create;
  FField := AField;
  FValue := AValue;
end;

function TNode.IsEmpty: Boolean;
begin
  Result := Trim(FValue) = '';
end;

constructor TQueryTree.Create;
begin
  inherited Create(True);
end;

function TQueryTree.AddCondition(const AField, AValue: string): TNode;
begin
  Result := TNode.Create(AField, AValue);
  Add(Result);
end;

function TQueryTree.ToFilter: string;
var
  Node: TNode;
begin
  Result := '';
  for Node in Self do
  begin
    if Result <> '' then
      Result := Result + ' AND ';
    Result := Result + Node.Field + ' = ' + QuotedStr(Node.Value);
  end;
end;

end.

touch.Query.pas:
unit Query;

interface

uses
  Tree;

procedure DropEmpty(ATree: TQueryTree);
function BuildFilter(ATree: TQueryTree): string;

implementation

procedure DropEmpty(ATree: TQueryTree);
var
  I: Integer;
  Node: TNode;
begin
  for I := ATree.Count - 1 downto 0 do
  begin
    Node := ATree[I];
    if Node.IsEmpty then
      ATree.Extract(Node);
  end;
end;

function BuildFilter(ATree: TQueryTree): string;
begin
  DropEmpty(ATree);
  Result := ATree.ToFilter;
end;

end.
